'use strict';
/* Profit math — JS port of backend/profit.py (the Python file is the reference).
 * Keep both in lockstep; backend/scripts/parity_check.cjs verifies the port
 * over fixtures generated by scripts/gen_fixtures.py.
 *
 * UMD-ish: browser -> window.OSRSProfit, node -> module.exports.
 */
(function (root, factory) {
  if (typeof module === 'object' && module.exports) module.exports = factory();
  else root.OSRSProfit = factory();
})(typeof self !== 'undefined' ? self : this, function () {
  // mirrors backend/config.py
  const GE_TAX_RATE = 0.02;
  const GE_TAX_EXEMPT_BELOW = 50;  // items selling at < this many gp are tax-exempt
  const GE_TAX_CAP = 5_000_000;    // per-item cap

  function geTax(sellPrice) {
    if (sellPrice == null || sellPrice < GE_TAX_EXEMPT_BELOW) return 0;
    return Math.min(Math.floor(sellPrice * GE_TAX_RATE), GE_TAX_CAP);
  }

  // Python round() — banker's rounding. Math.round differs on exact .5
  // (always up); this matches CPython's round-half-to-even.
  function pyRound(x) {
    const f = Math.floor(x);
    const diff = x - f;
    if (diff > 0.5) return f + 1;
    if (diff < 0.5) return f;
    return f % 2 === 0 ? f : f + 1;
  }

  // price_resolved: store.resolve() output. Returns [value, stale, source, vol, volSrc].
  function side(pr, mode, kind) {
    const buy = kind === 'buy';
    const conservative = mode === 'conservative';
    const sideKey = buy === conservative ? 'high' : 'low';
    const volKey = buy === conservative ? 'high_vol' : 'low_vol';
    const [value, stale, source] = pr[sideKey];
    const [v, vsrc] = pr[volKey];
    return [value, stale, source, v, vsrc];
  }

  /* Compute one recipe row. Returns null only if item metadata is missing.
   * Missing GE prices are tolerated: unpriced sides become null and the row
   * still renders (partial craft cost + cost_incomplete flag; HA/LA payouts
   * come from the item's static value, so they need no live prices at all).
   * recipe: {id, skill, level, members, product: {id, qty},
   *          materials: [{id, qty}], fee, note}  (the baked site data shape)
   * itemMap: {item_id: {name, image, limit, value}}
   * store:   OSRSPriceStore instance (resolve(itemId) -> per-side arrays or null)
   */
  function evaluateRecipe(recipe, itemMap, store, mode = 'conservative', craftCosts = null, allCosts = null) {
    const prodInfo = itemMap[recipe.product.id];
    if (!prodInfo) return null;
    const prodRes = store.resolve(recipe.product.id);
    let sellPrice = null, sellStale = null, sellSrc = null, sellVol = null;
    let prodBuy = null, prodBuyStale = null, prodBuySrc = null, prodBuyVol = null;
    if (prodRes) {
      [sellPrice, sellStale, sellSrc, sellVol] = side(prodRes, mode, 'sell');
      [prodBuy, prodBuyStale, prodBuySrc, prodBuyVol] = side(prodRes, mode, 'buy');
    }

    const materials = [];
    const fee = recipe.fee || 0;
    let cost = fee;       // mix: cheapest of buy vs craft per material
    let costDirect = fee;    // direct: buy every material, craft only the main product
    let costAll = fee;    // all: buy roots, craft every intermediate
    let costKnown = false, directKnown = false, allKnown = false;
    let costIncomplete = false, directIncomplete = false, allIncomplete = false;
    let minMatVol = null;
    for (const m of recipe.materials) {
      const info = itemMap[m.id];
      if (!info) return null;
      const res = store.resolve(m.id);
      let buyPrice = null, buyStale = null, buySrc = null, buyVol = null, matSell = null;
      if (res) {
        [buyPrice, buyStale, buySrc, buyVol] = side(res, mode, 'buy');
        [matSell] = side(res, mode, 'sell');
      }
      const craftUnit = craftCosts && (m.id in craftCosts) ? pyRound(craftCosts[m.id]) : null;
      const allUnit = allCosts && (m.id in allCosts) ? pyRound(allCosts[m.id]) : null;
      // direct: the material is always bought at the GE price
      if (buyPrice !== null) {
        costDirect += buyPrice * m.qty;
        directKnown = true;
      } else {
        directIncomplete = true;
      }
      // cheapest acquisition for this material: buy at GE price, or craft it if
      // that is cheaper; a material with neither leaves the cost incomplete
      let chosen;
      if (craftUnit !== null && (buyPrice === null || craftUnit < buyPrice)) {
        chosen = craftUnit;
      } else if (buyPrice !== null) {
        chosen = buyPrice;
      } else {
        chosen = null;
        costIncomplete = true;
      }
      if (chosen !== null) {
        cost += chosen * m.qty;
        costKnown = true;
      }
      // craft-all: always craft craftable materials (even when buying is
      // cheaper — that is the scenario being priced); buy the rest
      let chosenAll;
      if (allUnit !== null) {
        chosenAll = allUnit;
      } else if (buyPrice !== null) {
        chosenAll = buyPrice;
      } else {
        chosenAll = null;
        allIncomplete = true;
      }
      if (chosenAll !== null) {
        costAll += chosenAll * m.qty;
        allKnown = true;
      }
      materials.push({
        id: m.id,
        name: info.name,
        image_url: info.image,
        qty: m.qty,
        price: buyPrice,
        stale: buyStale,
        source: buySrc,
        vol: buyVol,
        sell: matSell,
        sell_tax: matSell == null ? 0 : geTax(matSell),
        craft: craftUnit,
      });
      if (buyVol !== null) {
        // how many crafts per 5m does this material's buy-side volume support?
        const supported = m.qty > 0 ? buyVol / m.qty : Infinity;
        minMatVol = minMatVol === null ? supported : Math.min(minMatVol, supported);
      }
    }

    if (!costKnown) cost = null;
    if (!directKnown) costDirect = null;
    if (!allKnown) costAll = null;
    const gross = sellPrice !== null ? sellPrice * recipe.product.qty : null;
    const taxTotal = sellPrice !== null ? geTax(sellPrice) * recipe.product.qty : null;
    const net = gross === null || cost === null ? null : gross - taxTotal - cost;
    const netPct = net !== null && cost && cost > 0 ? pyRound(((net / cost) * 100) * 10) / 10 : null;

    // 4h buy-limit cap: limited by every material and the product itself
    let maxCrafts = null;
    let limited = false;
    for (const m of recipe.materials) {
      const limit = itemMap[m.id].limit;
      if (limit == null) { limited = true; continue; }
      const c = Math.floor(limit / m.qty);
      maxCrafts = maxCrafts === null ? c : Math.min(maxCrafts, c);
    }
    const prodLimit = prodInfo.limit;
    if (prodLimit == null) {
      limited = true;
    } else {
      const c = Math.floor(prodLimit / recipe.product.qty);
      maxCrafts = maxCrafts === null ? c : Math.min(maxCrafts, c);
    }
    if (maxCrafts === null) maxCrafts = null; // no buy limits known at all
    const net4h = limited || !maxCrafts || net === null ? null : net * maxCrafts;

    const volume = sellVol === null ? null
      : (minMatVol !== null ? Math.trunc(Math.min(sellVol, minMatVol)) : Math.trunc(sellVol));

    const toolsOut = [];
    for (const t of recipe.tools || []) {
      const entry = { id: t.id ?? null, name: t.name, image_url: null,
                      buy: null, buy_vol: 0, sell: null, tax: 0 };
      if (entry.id && itemMap[entry.id]) {
        const info = itemMap[entry.id];
        entry.image_url = info.image;
        const res = store.resolve(entry.id);
        if (res) {
          entry.buy = res.high[0];
          entry.buy_vol = res.high_vol[0];
          entry.sell = res.low[0];
          entry.tax = res.low[0] == null ? 0 : geTax(res.low[0]);
        }
      }
      toolsOut.push(entry);
    }

    return {
      recipe_id: recipe.id,
      skill: recipe.skill,
      level: recipe.level,
      extra_skills: recipe.extra_skills || [],
      xp: recipe.xp != null ? recipe.xp : 0,
      members: recipe.members,
      product: {
        id: recipe.product.id,
        name: prodInfo.name,
        image_url: prodInfo.image,
        qty: recipe.product.qty,
        price: sellPrice,
        buy: prodBuy,
        buy_vol: prodBuyVol,
        value: prodInfo.value ?? null,
        stale: sellStale,
        source: sellSrc,
        vol: sellVol,
      },
      materials,
      fee: recipe.fee || 0,
      cost_direct: costDirect === null ? null : pyRound(costDirect),
      direct_incomplete: directIncomplete,
      cost: cost === null ? null : pyRound(cost),
      cost_incomplete: costIncomplete,
      cost_all: costAll === null ? null : pyRound(costAll),
      all_incomplete: allIncomplete,
      gross,
      tax: taxTotal,
      net: net === null ? null : pyRound(net),
      net_pct: netPct,
      volume: volume === null ? null : Math.max(volume, 0),
      max_crafts_4h: maxCrafts,
      net_4h: net4h === null ? null : pyRound(net4h),
      mode,
      note: recipe.note ?? null,
      tools: toolsOut,
      facilities: recipe.facilities || [],
    };
  }

  /* Evaluate every recipe (the old /api/recipes route logic, minus filters).
   * Craft costs are computed to a fixed point: repeated sweeps until no
   * product's per-unit cost improves. craftCosts holds the cheapest mix (per
   * material: buy or recursive craft), so a material's ⚒ price always equals
   * the fully recursive cheapest craft decomposition shown in its own row (and
   * expanded in the detail table) — e.g. Uncooked pizza inside Plain pizza
   * prices cheese via milk, not at the cheese GE price. allCosts holds the
   * craft-everything decomposition (roots bought, every intermediate crafted).
   * Each sweep can only lower costs (materials gain cheaper options), so this
   * converges; the sweep cap just bounds pathological recipe cycles. Keep in
   * lockstep with backend/profit.py (parity_check.cjs verifies over fixtures).
   */
  function evaluateAll(recipes, itemMap, store, mode = 'conservative') {
    const materialIds = new Set();
    for (const r of recipes) for (const m of r.materials) materialIds.add(m.id);
    const craftCosts = {};
    const allCosts = {};
    const MAX_SWEEPS = 10;
    for (let sweep = 0; sweep < MAX_SWEEPS; sweep++) {
      let changed = false;
      for (const r of recipes) {
        const pid = r.product.id;
        if (!materialIds.has(pid)) continue;
        const row = evaluateRecipe(r, itemMap, store, mode, craftCosts, allCosts);
        if (!row || row.product.qty < 1) continue;
        for (const [key, costs] of [['cost', craftCosts], ['cost_all', allCosts]]) {
          if (row[key] === null) continue;
          const perUnit = row[key] / row.product.qty;
          if (!(pid in costs) || perUnit < costs[pid]) {
            costs[pid] = perUnit;
            changed = true;
          }
        }
      }
      if (!changed) break;
    }
    const rows = [];
    let skippedNoPrice = 0;
    for (const r of recipes) {
      const row = evaluateRecipe(r, itemMap, store, mode, craftCosts, allCosts);
      if (!row) { skippedNoPrice++; continue; }
      rows.push(row);
    }
    return { rows, skippedNoPrice };
  }

  return { geTax, pyRound, evaluateRecipe, evaluateAll };
});
